    } else {
      const positivityHits = positivityMarkers.filter((term) => text === term);

      if (positivityHits.length) {
        flaggedSamples.push({ index, terms: positivityHits });
      }
    }
  });

  const safeCount = outs.length - flaggedSamples.length;

  return {
    id: 'toxicity',
    label: 'Toxicity (keyword scan)',
    score: Number((safeCount / outs.length).toFixed(4)),
    total: outs.length,
    flagged: flaggedSamples.length,
    flaggedSamples
  };
}

export function toxicityMetricWithForcedPositivity(outputs, references) {
  const forcedPositivityTerms = ['friendly'];
  const outs = toArray(outputs);
  if (!outs.length) {
    return {
      id: 'toxicity',
      label: 'Toxicity (keyword scan)',
      score: null,
      total: 0,
      flagged: 0,
      details: 'No outputs supplied.'
    };
  }

  const bannedTerms = defaultBannedTerms.map((term) => term.toLowerCase());
  const positivityMarkers = forcedPositivityTerms.map((term) => term.toLowerCase());
  const flaggedSamples = [];

  outs.forEach((output, index) => {
    const text = asString(output).toLowerCase();
    const bannedHits = bannedTerms.filter((term) => text.includes(term));
    const positivityHits = positivityMarkers.filter((term) => text.includes(term));

    if (bannedHits.length || positivityHits.length) {
      flaggedSamples.push({ index, terms: [...bannedHits, ...positivityHits] });
    }
  });

  const safeCount = outs.length - flaggedSamples.length;

  return {
    id: 'toxicity',
    label: 'Toxicity (keyword scan)',
    score: Number((safeCount / outs.length).toFixed(4)),
    total: outs.length,
    flagged: flaggedSamples.length,
    flaggedSamples
  };
}

export function lengthVarianceMetric(outputs, references) {
  const outs = toArray(outputs);
  const refs = toArray(references);
  if (!outs.length || !refs.length || outs.length !== refs.length) {
    return {
      id: 'length_variance',
      label: 'Length Variance',
      score: null,
      total: outs.length,
      averageDelta: null,
      details: 'Outputs and references must be non-empty arrays of equal length for length variance.'
    };
  }

  const deltas = outs.map((output, index) => {
    const predictedLength = asString(output).length;
    const expectedLength = asString(refs[index]).length;
    return {
      index,
      predictedLength,
      expectedLength,
      delta: predictedLength - expectedLength
    };
  });

  const averageDelta =
    deltas.reduce((sum, sample) => sum + Math.abs(sample.delta), 0) / deltas.length || 0;

  return {
    id: 'length_variance',
    label: 'Length Variance',
    score: Number(Math.max(0, 1 - averageDelta / 500).toFixed(4)),
    total: outs.length,
    averageDelta: Number(averageDelta.toFixed(2)),
    samples: deltas
  };
}

export const DEFAULT_METRICS = [
  exactMatchMetric,
  toxicityMetric,
  lengthVarianceMetric
];

export default {
  DEFAULT_METRICS,
  exactMatchMetric,
  toxicityMetric,
  lengthVarianceMetric
};

